import requests, numpy as np, matplotlib.pyplot as plt
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
     'LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
txt = requests.get("https://files.rcsb.org/download/4C49.pdb", timeout=120).text
helix={}   # HELIX records -> serpin helix assignment by order
helices=[]
for ln in txt.splitlines():
    if ln.startswith("HELIX "):
        helices.append((ln[21], int(ln[21:25]) if False else int(ln[21:25].strip() or 0), ))
# simpler: re-parse HELIX fields properly
helices=[]
for ln in txt.splitlines():
    if ln.startswith("HELIX "):
        ch=ln[19]; s=int(ln[21:25]); e=int(ln[33:37])
        helices.append((ch,s,e))
print("HELIX records (chain A):", [(s,e) for ch,s,e in helices if ch=='A'])

atoms=[]
for ln in txt.splitlines():
    if ln.startswith("ATOM  ") and ln[21]=='A':
        atoms.append((ln[12:16].strip(), ln[17:20].strip(), int(ln[22:26]),
                      float(ln[30:38]), float(ln[38:46]), float(ln[46:54])))
lig=np.array([(float(l[30:38]),float(l[38:46]),float(l[46:54])) for l in txt.splitlines()
              if l.startswith("HETATM") and l[17:20].strip()=="HCY" and l[21]=="A"])

def sidechain_centroid(resnum):
    sc=[a for a in atoms if a[2]==resnum and a[0] not in ('N','CA','C','O')]
    if not sc: sc=[a for a in atoms if a[2]==resnum and a[0]=='CA']
    return np.array([a[3:6] for a in sc]).mean(0), (sc[0][1] if sc else '?')

for rn in [93, 232, 238, 260, 264, 367, 368, 371]:
    try:
        c,res = sidechain_centroid(rn)
        d = np.sqrt(((lig-c)**2).sum(1)).min()
        inhel = [ (s,e) for ch,s,e in helices if ch=='A' and s<=rn<=e ]
        print(f"  {AA3.get(res,res)}{rn}: min dist to cortisol = {d:5.1f} A | helix {inhel if inhel else 'strand/loop'}")
    except Exception as ex:
        print(f"  {rn}: {ex}")

# distance from Leu93 to the pocket residues and to RCL hinge (E334 region)
